def select_reactions(apps, schema_editor):
    Site = apps.get_model("blog", "SiteConfiguration")
    Emoji = apps.get_model("blog", "CommentEmoji")
    for site in Site.objects.exclude(article_reaction_emoji_pack_id=None).iterator():
        limit = max(1, min(9, site.article_reaction_limit or 6))
        ids = list(
            Emoji.objects.filter(pack_id=site.article_reaction_emoji_pack_id)
            .order_by("order", "id")
            .values_list("id", flat=True)[:limit]
        )
        for slot, emoji_id in enumerate(ids, start=1):
            Emoji.objects.filter(pk=emoji_id).update(reaction_order=slot)


def dedupe_users(apps, schema_editor):
    Vote = apps.get_model("blog", "ArticleReactionVote")
    groups = (
        Vote.objects.exclude(user_id=None)
        .values("article_id", "user_id")
        .annotate(total=Count("id"))
        .filter(total__gt=1)
    )
    for group in groups.iterator():
        ids = list(
            Vote.objects.filter(
                article_id=group["article_id"],
                user_id=group["user_id"],
            )
            .order_by("-updated_at", "-id")
            .values_list("id", flat=True)
        )
        Vote.objects.filter(pk__in=ids[1:]).delete()


